// Gradient of whites, not a flat color: lines are brightest near the top and
// bottom edges of the field and dimmest through the vertical middle — which
// is also where the hero's text block sits, so the busiest part of the
// pattern naturally recedes behind the text instead of competing with it.
// (Text legibility is additionally guaranteed independent of this — see the
// dedicated scrim in page.tsx — this gradient is a visual choice on top of
// that guarantee, not a substitute for it.)
function ContourTile({ gradientId }: { gradientId: string }) {
  return (
    <svg
      className={styles.tile}
      viewBox={`0 0 ${TILE_W} ${TILE_H}`}
      preserveAspectRatio="none"
      fill="none"
    >
      <defs>
        <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%"   stopColor="#FFFFFF" stopOpacity="0.16" />
          <stop offset="30%"  stopColor="#FFFFFF" stopOpacity="0.07" />
          <stop offset="50%"  stopColor="#FFFFFF" stopOpacity="0.05" />
          <stop offset="70%"  stopColor="#FFFFFF" stopOpacity="0.07" />
          <stop offset="100%" stopColor="#FFFFFF" stopOpacity="0.15" />
        </linearGradient>
      </defs>
      <g stroke={`url(#${gradientId})`} strokeWidth={SW} strokeLinecap="round" strokeLinejoin="round">
        {LINES.map((d, i) => (
          <path key={i} d={d} />
        ))}
      </g>
    </svg>
  )
}

// Parallax factor: the background travels at 35% of the page's scroll speed,
// so it visibly lags behind the foreground content as the hero scrolls past —
// a background that reads as "further away," not just a static backdrop.
// Written straight to the DOM via a ref + rAF-batched scroll listener rather
// than React state, so a fast scroll never triggers a React re-render per
// frame — only a direct style write, the standard pattern for scroll-linked
// transforms. Skipped entirely under prefers-reduced-motion.
const PARALLAX_FACTOR = 0.35

export default function HeroField() {
  const fieldRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches
    if (prefersReduced) return

    const el = fieldRef.current
    if (!el) return

    // Once the hero itself has fully scrolled out of view there's nothing to
    // gain from moving it further — clamp so the transform (and the work of
    // computing it) tops out instead of growing for the rest of the page.
    const maxOffset = () => (el.parentElement?.getBoundingClientRect().height ?? 900) * (1 - PARALLAX_FACTOR)

    let ticking = false
    const apply = () => {
      ticking = false
      const offset = Math.min(window.scrollY * (1 - PARALLAX_FACTOR), maxOffset())
      el.style.transform = `translateY(${offset}px)`
    }
    const onScroll = () => {
      if (ticking) return
      ticking = true
      requestAnimationFrame(apply)
    }

    apply()
    window.addEventListener('scroll', onScroll, { passive: true })
    return () => window.removeEventListener('scroll', onScroll)
  }, [])

  return (
    <div aria-hidden="true" className={styles.field} ref={fieldRef}>
      <div className={styles.track}>
        <ContourTile gradientId="contour-grad-a" />
        <ContourTile gradientId="contour-grad-b" />
      </div>
    </div>
  )
}
